import Header from "@/components/Header";
import Footer from "@/components/Footer";
import { sampleProject } from "@/lib/mock-data";

export default async function ProjectPage({params}:{params:Promise<{slug:string}>}){
  const {slug} = await params;
  const p = {...sampleProject, slug, title: slug.replaceAll("-"," ").toUpperCase()};
  return (
    <>
      <Header />
      <main className="page-shell">
        <h1 className="project-title">{p.title}</h1>
        <div className="project-hero">IMAGEN PRINCIPAL</div>
        <section className="project-copy">
          <h2>{p.location} | {p.area} | {p.year}</h2>
          {p.description.map((x,i)=><p key={i}>{x}</p>)}
        </section>
        <section className="gallery">
          {Array.from({length:15}).map((_,i)=><div className="img" key={i}>IMG {i+1}</div>)}
        </section>
      </main>
      <Footer />
    </>
  )
}
